from datetime import date, timedelta
from calendar import monthrange


def recur(start: str, rule: str, count: int) -> list[str]:
    first = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    step = int(parts[1])
    weekdays = {name: i for i, name in enumerate(
        ("MO", "TU", "WE", "TH", "FR", "SA", "SU")
    )}

    if kind == "DAILY":
        return [
            (first + timedelta(days=i * step)).isoformat()
            for i in range(count)
        ]

    result = []

    if kind == "WEEKLY":
        days = sorted(weekdays[name] for name in parts[2].split(","))
        monday = first - timedelta(days=first.weekday())

        while True:
            for day in days:
                candidate = monday + timedelta(days=day)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            monday += timedelta(weeks=step)

    if kind == "MONTHLY":
        month_index = first.year * 12 + first.month - 1
        number = int(parts[2])
        target_weekday = weekdays[parts[3]] if len(parts) == 4 else None

        while True:
            year, month_zero = divmod(month_index, 12)
            month = month_zero + 1
            first_weekday, last_day = monthrange(year, month)

            if target_weekday is None:
                day = last_day if number == -1 else number
            elif number == -1:
                last_weekday = (first_weekday + last_day - 1) % 7
                day = last_day - (last_weekday - target_weekday) % 7
            else:
                day = (
                    1
                    + (target_weekday - first_weekday) % 7
                    + 7 * (number - 1)
                )

            if day <= last_day:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result

            month_index += step

    if kind == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        year = first.year

        while True:
            if day <= monthrange(year, month)[1]:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            year += step
